n  // models as well as bodies and are kept.\n  var BODY_WORDS = [\"coupe\", \"coup\", \"cabriolet\", \"cabrio\", \"convertible\", \"roadster\", \"sedan\", \"saloon\", \"wagon\", \"estate\", \"hatchback\", \"hardtop\", \"fastback\"];\n  function carWords(s, make){ var mk = String(make || \"\").toLowerCase(); return String(s || \"\").toLowerCase().replace(/é/g, \"e\").replace(/[^a-z0-9]+/g, \" \").split(\" \").filter(function(w){ return w && w !== mk && mk.split(/[^a-z0-9]+/).indexOf(w) < 0 && BODY_WORDS.indexOf(w) < 0; }).join(\" \"); }\n  function rungShown(l, lines){ var t = carWords(carTitle(l), l.make); return (lines || []).filter(function(x){ return carWords(x, l.make) !== t; }); }\n  function samLine(l){\n    var ls = l.swap ? [] : (l.sam_lines || []);\n    // A market still being read says so (no range, no Market Check) until it comes or the page stops asking.\n    var reading = !l.swap && (l.market === undefined || (l.market && l.market.kind === \"pending\"));\n    if (!ls.length && !reading) return null;\n    return { html: (reading ? '<p class=\"reading\">' + esc((l.market && l.market.kind === \"pending\" && l.market.line) || READING_LINE) + \"</p>\" : \"\") + ls.map(function(x){ return x.kind === \"range\" ? \"<p>\" + rungHtml({ rungLines: rungShown(l, x.rung) }) + esc(x.text) + \"</p>\" : '<p class=\"same\">' + esc(x.lead) + saleLink(x.link, x.url) + esc(x.tail) + \"</p>\"; }).join(\"\") };\n  }\n  // SPEC CHIPS under the bid line: gearbox, colours, title status and the VIN shortened, only what the listing states.\n  // The VIN pill is not shown on the card (Buy redesign Stage 1).\n  function chipsHtml(l){ var c = (l.chips || []).filter(function(x){ return !/^VIN\\b/i.test(String(x)); }); return c.length ? '<p class=\"specs\">' + c.map(function(x){ return '<span class=\"spec\">' + esc(x) + \"</span>\"; }).join(\"\") + \"</p>\" : \"\"; }\n  // HAVE SAM KEEP LOOKING on the card: a Task from the spec this page has established (every pill and every typed\n  // change is in conv.chatState.filters), named by the same words as the header.\n  var CUR_Q = \"\";\n  function keepHref(q){ return \"/tasks/mine?seed=buy&words=\" + encodeURIComponent(String(q || \"\").slice(0, 300)) + \"&filters=\" + encodeURIComponent(JSON.stringify((conv.chatState && conv.chatState.filters) || {})); }\n  function keepPill(){ return REL_TASKS ? '<a class=\"kpill\" data-keep data-keepcard target=\"_blank\" rel=\"noopener\" href=\"' + esc(keepHref(CUR_Q)) + '\">Have Sam keep looking</a>' : \"\"; }\n  // A THIN CARD SHOWS ITS SALES (Sam, Oct 19 2026; Lane C): when the engine's answer has no range and the engine sends\n  // its own sale rows for the card (l.market.rows, flagged l.market.cardListsSales, lib/live/search.js), the card lists\n  // them under the Sam line: compact rows, each with a thumbnail or the marked no-photo slot, the record's own title, the\n  // month and year, the mileage at that sale when stated, and the price. No venue name and no link. Nothing is computed\n  // here and nothing shows on a card with a range.\n  var ROWS_CSS_DONE = false;\n  function rowsCss(){ if (ROWS_CSS_DONE) return; ROWS_CSS_DONE = true; var st = document.createElement(\"style\"); st.textContent = \".crows{margin:8px 0 0;display:flex;flex-direction:column;gap:6px}.crow{display:grid;grid-template-columns:52px minmax(0,1fr) auto;gap:10px;align-items:center}.cth{width:52px;height:39px;object-fit:cover;border-radius:4px;background:var(--div,#E2DED3);display:block}.cth.nop{display:flex;align-items:center;justify-content:center;font:500 10px/1.1 var(--sans);color:var(--sec);text-align:center}.ct{display:block;font:500 13px/1.3 var(--sans);color:var(--ink);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.cm{display:block;font:400 12px/1.3 var(--sans);color:var(--sec)}.cp{font:600 13px/1.3 var(--sans);color:var(--ink);white-space:nowrap}\"; document.head.appendChild(st); }\n  function rowsHtml(l){\n    var m = l.market; if (l.swap || !m || m.cardListsSales !== true || !m.rows || !m.rows.length) return \"\";\n    rowsCss();\n    return '<div class=\"crows\">' + m.rows.map(function(r){\n      var when = [monShort(r.date), r.mi != null ? num(r.mi) + \" miles at sale\" : \"\"].filter(Boolean).join(\", \");\n      return '<div class=\"crow\">' + (r.image ? '<img class=\"cth\" src=\"' + esc(r.image) + '\" alt=\"\" loading=\"lazy\" decoding=\"async\" referrerpolicy=\"no-referrer\" onerror=\"this.outerHTML=\\'<span class=&quot;cth nop&quot;>No photo</span>\\'\">' : '<span class=\"cth nop\">No photo</span>') +\n        '<span><span class=\"ct\">' + esc(r.title || \"\") + '</span><span class=\"cm\">' + esc(when) + '</span></span><span class=\"cp\">' + (r.price ? usd(r.price) : \"\") + \"</span></div>\";\n    }).join(\"\") + \"</div>\";\n  }\n  function card(l, big, eager){\n    CARDS[l.id] = l;\n    var al = ALERTS[l.id]; if (al && al.ended) return soldCard(l, al);\n    var line = samLine(l), hist = sameCar(l).length > 0;\n    var hasMc = !l.swap && !!(l.market && l.market.query);\n    var src = [pillText(l), l.reserve === \"none\" ? \"No reserve\" : \"\"].filter(Boolean).join(\" · \");\n    var arrow = '<svg viewBox=\"0 0 12 12\" aria-hidden=\"true\"><path d=\"M3.5 8.5l5-5M4.5 3.5h4v4\"/></svg>';\n    var clock = '<svg viewBox=\"0 0 16 16\" aria-hidden=\"true\"><circle cx=\"8\" cy=\"8\" r=\"6\"/><path d=\"M8 4.8V8l2.2 1.4\"/></svg>';\n    var ph = photoHtml(l, eager), money = moneyHtml(l);\n    if (ph && money) ph = ph.replace(/<\\/div>$/, money + \"</div>\");\n    return '<article class=\"car' + (l.photo_url ? \"\" : \" nophoto\") + (l.swap ? \" swapped\" : \"\") + '\" data-id=\"' + l.id + '\">' + ph +\n      '<div class=\"tx\">' + (ph ? \"\" : money) + '<p class=\"src\">' + esc(src) + '</p><div class=\"trow\"><h3><a href=\"' + esc(l.url) + '\" target=\"_blank\" rel=\"noopener\" data-gas-event=\"auction_clickout\" data-gas-source=\"' + esc(l.source||\"\") + '\" data-gas-listing-id=\"' + esc(String(l.id||\"\")) + '\">' + esc(carTitle(l)) + \"</a></h3></div>\" + metaLine(l) + chipsHtml(l) +\n      (l.swap ? '<p class=\"tagline\"><span class=\"tag\">Engine swapped</span></p>' : \"\") +\n      (line ? '<div class=\"sl\"><span class=\"who\">Sam</span>' + line.html + rowsHtml(l) + \"</div>\" : \"\") +\n      // THE CARD FOOT (Sam, Oct 15 2026): the history pill's own reserved line, then the action row, pinned to the\n      // card's bottom so View auction and Market Check sit on one line across a row; the line stays (empty) on a\n      // card without the pill.\n      '<div class=\"hrow\">' + (hist ? '<button type=\"button\" class=\"act hact\" data-hist=\"' + l.id + '\" aria-expanded=\"false\" aria-haspopup=\"dialog\">' + clock + esc(priorWords(sameCar(l)).button) + \"</button>\" : \"\") + \"</div>\" +\n      '<div class=\"acts\"><a class=\"vauc\" href=\"' + esc(l.url) + '\" target=\"_blank\" rel=\"noopener\" data-gas-event=\"auction_clickout\" data-gas-source=\"' + esc(l.source||\"\") + '\" data-gas-listing-id=\"' + esc(String(l.id||\"\")) + '\">View auction ' + arrow + \"</a>\" +\n      (hasMc ? '<button type=\"button\" class=\"act\" data-mc=\"' + l.id + '\" aria-expanded=\"false\" data-gas-event=\"market_check_open\" data-gas-source=\"buy\">' + (REL_MC ? \"Market Check\" : \"Sold prices\") + \"</button>\" : \"\") +\n      \"</div></div></article>\";\n  }\n  // THE ADAPTIVE GRID: 1 wide, 2 equal, 3 across, 2 x 2, 3 + 2 centred, then 3 across with six shown and\n  // Show more (CSS on .cgrid.nN; engine-swapped cars come last from the engine).\n  function gridBlock(cards){\n    var n = Math.min(cards.length, 6);\n    var html = '<div class=\"cgrid n' + n + '\">' + cards.map(function(l, i){ var h = card(l, false, i < 6); return i >= 6 ? h.replace('<article class=\"car', '<article hidden class=\"car') : h; }).join(\"\") + \"</div>\";\n    return html + (cards.length > 6 ? '<p class=\"morerow\"><a href=\"#\" data-more>Show ' + Math.min(6, cards.length - 6) + \" more</a></p>\" : \"\");\n  }\n  // MARKET CHECK DRAWER: full width under the row holding the card. Read from the card's OWN spec key and engine\n  // answer (POST /api/buySearch {action:\"panel\", id}, lib/live/search.js panelOf), never a second free-text\n  // Market Check call, so the range, the count, the sentence and the three sales are the card line's own. A\n  // range on the card is a range here; no range on the card, none here.\n  function closeOverlays(except){\n    Array.prototype.forEach.call(document.querySelectorAll(\".mcdrawer\"), function(x){ if (x !== except) { var b = document.querySelector('[data-mc=\"' + x.getAttribute(\"data-for\") + '\"]'); if (b) b.setAttribute(\"aria-expanded\", \"false\"); x.remove(); } });\n    Array.prototype.forEach.call(document.querySelectorAll(\".hpop,.hscrim\"), function(x){ if (x !== except) x.remove(); });\n    Array.prototype.forEach.call(document.querySelectorAll(\"[data-hist][aria-expanded=true]\"), function(b){ b.setAttribute(\"aria-expanded\", \"false\"); });\n  }\n  function venueOf(c){ var p = String(c.platform || \"\"); if (p && !/^others?$/i.test(p)) return p; try { var h = new URL(c.url).hostname.replace(/^www\\./, \"\").split(\".\")[0]; return HOUSE[h] || cap(h); } catch(e){ return \"\"; } }\n  function drawerHtml(l, j){\n    var m = (j && j.market && j.market.kind !== \"pending\" ? j.market : null) || l.market || null;\n    var out = [];\n    if (m && m.rungLines && m.rungLines.length) out.push('<p class=\"md-g\">' + rungHtml(m) + \"</p>\");\n    if (j && j.engineAnswer && window.sellsForCardHtml) { out.push(window.sellsForCardHtml(j.engineAnswer, {})); } else {\n      out.push('<p class=\"md-t\">What similar cars sold for</p>');\n      if (m && m.kind === \"range\" && m.low > 0 && m.high > 0) {\n        out.push('<p class=\"md-r\">' + usd(m.low) + ' <span>to</span> ' + usd(m.high) + \"</p>\");\n        out.push('<p class=\"md-s\">The middle half of comparable sales landed here.' + (Number(m.count) > 0 ? \" Based on \" + cnt(m.count) + \" sales in \" + esc(m.window || \"the past year\") + \".\" : \"\") + \"</p>\");\n      } else if (m && m.soldLine) out.push('<p class=\"md-s\">' + esc(m.soldLine) + \"</p>\");\n    }\n    if (m && m.kind === \"range\" && m.low > 0 && m.high > 0) {\n      var mi = m.miles;\n      if (mi && mi.soldN >= 8) { var pct = mi.fewer / mi.soldN; out.push('<p class=\"md-o\">' + (pct <= 0.1 ? \"This one has fewer miles than almost all of them.\" : pct < 0.25 ? \"This one has fewer miles than most of them.\" : pct > 0.75 ? \"This one has more miles than most of them.\" : \"This one has about typical miles for them.\") + \"</p>\"); }\n    }\n    var rep = (j && j.representative) || {}, three = [rep.closest, rep.high, rep.low].filter(Boolean);\n    if (three.length) out.push('<div class=\"md-sales\">' + three.map(function(c){\n      var bits = esc([monShort(c.date), c.mi ? num(c.mi) + \" miles\" : \"\"].filter(Boolean).join(\" · \"));\n      var ph = c.image ? '<span class=\"md-ph\"><img src=\"' + esc(c.image) + '\" alt=\"\" loading=\"lazy\" referrerpolicy=\"no-referrer\" onerror=\"this.parentNode.remove()\"></span>' : \"\";\n      var ow = (c.offWindow === true && c.year && l.year) ? ('<span class=\"md-ow\">A ' + c.year + ' car, a few years from the ' + l.year + ' searched.</span>') : \"\";\n      var body = ph + '<span class=\"md-b\"><span>' + bits + \"</span><b>\" + (c.price ? usd(c.price) : \"\") + \"</b><span>\" + esc(venueOf(c)) + \"</span>\" + ow + \"</span>\";\n      return okUrl(c.url) ? '<a class=\"md-sale\" href=\"' + esc(c.url) + '\" target=\"_blank\" rel=\"noopener\" data-gas-event=\"receipt_click\" data-gas-source=\"' + esc(c.platformSlug || String(venueOf(c)).toLowerCase().replace(/[^a-z0-9]/g, \"\")) + '\">' + body + \"</a>\" : '<span class=\"md-sale\">' + body + \"</span>\";\n    }).join(\"\") + \"</div>\");\n    out.push(alertSwitchHtml(l));\n    out.push(watchHtml(l));\n    var slug = String((m && m.query) || (l.market && l.market.query) || \"\").toLowerCase().trim().replace(/[^a-z0-9]+/g, \"-\").replace(/^-+|-+$/g, \"\");\n    out.push('<p class=\"md-l\">' + (REL_MC ? '<a href=\"/market-check?car=' + encodeURIComponent(slug) + '\">Open full Market Check →</a> ' : \"\") + '<button type=\"button\" class=\"md-x\" data-mcclose aria-label=\"Close\">&times;</button></p>');\n    return out.join(\"\");\n  }\n  function openDrawer(btn){\n    var art = btn.closest(\".car\"), id = art.getAttribute(\"data-id\"), l = CARDS[id] || {}, grid = art.closest(\".cgrid\");\n    var open = document.querySelector('.mcdrawer[data-for=\"' + id + '\"]');\n    closeOverlays();\n    if (open) return;\n    // The last card in this card's row: the drawer goes after it, spanning the whole row.\n    var row = Array.prototype.filter.call(grid.querySelectorAll(\"article.car:not([hidden])\"), function(c){ return Math.abs(c.offsetTop - art.offsetTop) < 4; });\n    var last = row[row.length - 1] || art;\n    var dr = document.createElement(\"div\"); dr.className = \"mcdrawer\"; dr.setAttribute(\"data-for\", id); dr.setAttribute(\"role\", \"region\"); dr.setAttribute(\"aria-label\", \"What similar cars sold for\");\n    dr.innerHTML = '<p class=\"md-t\">What similar cars sold for</p><p class=\"md-s\"><span class=\"dots\" aria-hidden=\"true\"><i></i><i></i><i></i></span></p>';\n    last.insertAdjacentElement(\"afterend\", dr); btn.setAttribute(\"aria-expanded\", \"true\");\n    panelRun(dr, l);\n  }\n  // The panel's one read. A fresher answer for the same spec replaces the card's own line too, so the card\n  // and its panel never disagree on screen. A read that fails shows the card's own line, never \"no range\".\n  var PANEL = {};\n  function panelRun(dr, l){\n    var show = function(j){\n      if (j && j.market && j.market.kind !== \"pending\" && CARDS[l.id]) { var was = JSON.stringify(l.sam_lines || []); l.market = j.market; if (j.sam_lines) l.sam_lines = j.sam_lines; if (JSON.stringify(l.sam_lines || []) !== was) cardLine(l); }\n      if (dr.isConnecte