export default async function handler(req, res) {
  // LAUNCH STAGE (Oct 2026, Job 2): a public request to this address, while Buy is not yet released
  // at the current stage, gets a TEMPORARY redirect to /sell before any of the work below runs -
  // never permanent, so a stage rollback or a later release does not leave a stale 301 cached
  // anywhere. Crew passes through untouched.
  if (!isReleased("buy", req)) { res.setHeader("Cache-Control", "no-store"); res.setHeader("Location", "/sell"); return res.status(302).end(); }
  // The landing's "Updated" line (the shared last-ingest date) and its "A real example" band (the live
  // Buy search, cached an hour; never waits more than a few seconds).
  // THE PAGE NEVER WAITS ON THE DATABASE (Sam, Oct 16 2026): on a slow database these reads held the HTML 12 s before
  // the search could start. Each gets PAGE_WAIT_MS: a value this instance already holds is used at once, a read that
  // comes back in time is used, and otherwise the page goes out with the last known value or the neutral line (no
  // count, no "Updated", no example band). The read keeps running after the page is sent (waitUntil), so this instance
  // holds it for the next page, and the page fills the landing in itself (?part=landing below).
  if (/[?&]part=landing(&|$)/.test(String(req.url || ""))) {
    const [updated, band] = await Promise.all([lastUpdatedDate(supabaseEnv()).catch(() => null), exampleBand(supabaseEnv()).catch(() => null)]);
    res.setHeader("Cache-Control", "private, no-store"); res.setHeader("X-Robots-Tag", "noindex");
    return res.status(200).json({ html: band === undefined && !updated ? null : landingHtml({ updated, band, tasks: isReleased("tasks", req) }) });
  }
  const LATE = Symbol("late");
  const [n0, up0, band0] = await Promise.all([inTime(countLive(), LATE), inTime(lastUpdatedDate(supabaseEnv()).catch(() => null), LATE), inTime(exampleBand(supabaseEnv()).catch(() => null), LATE)]);
  const late = n0 === LATE || up0 === LATE || band0 === LATE;
  const n = n0 === LATE ? liveCount.n : n0, updated = up0 === LATE ? null : up0, band = band0 === LATE ? undefined : band0;
  const asOf = new Date().toLocaleDateString("en-US", { month: "long", day: "numeric", year: "numeric", timeZone: "America/Los_Angeles" });
  const lead = n ? `Sam is following ${n.toLocaleString("en-US")} collector cars live at auction as of ${asOf}, each one shown with what cars like it have actually sold for.`
    : `Sam follows the collector cars live at auction as of ${asOf}, each one shown with what cars like it have actually sold for.`;
  const TITLE = "Collector cars for sale, by what they actually sell for";
  // Search: /buy itself is indexable; a conversation is never a separate URL (?q= starts one in the
  // page) and any query-string variant is noindex with /buy as its canonical.
  const hasQuery = /\?./.test(String(req.url || ""));
  const robots = hasQuery ? "noindex, follow" : "index, follow";
  // Crew (gas_crew=ok, the One Box crew gate's cookie) only changes caching below and window.GAS_CREW; the
  // rail is the same full page list for everyone (Round D lifted the Oct 7 public nav lockdown).
  const crew = isCrewRequest(req);
  // The palette switcher (Sam, Oct 2026 palette round; Lane A's lib/appShell.js paletteHead): the same showPal rule as
  // Market Check, Business and Tasks. The bar is never shared-cached (showPal joins the private, no-store list below).
  const showPal = crew || isTesterRequest(req) || /[?&]palette=1\b/.test(String(req.url || ""));
  // THE RAIL: the shared app shell (lib/appShell.js, Oct 2026), the same rail, page list, tokens and phone
  // header row as Market Check, Sell and Tasks. Buy's own block in it is "Your searches" (and Saved
  // searches when signed in, and Before it ends), filled by the client into #searches exactly as before.
  // The phone header row carries the logo, Buy's "Your searches" pill, the menu and the docked sign in.
  const MVIS = '<button type="button" class="mvis" data-mvisits aria-expanded="false" aria-controls="mvlist">Your searches</button>';
  const MENU = '<button type="button" class="gas-menu"';
  let shell = railOpenHtml({ active: "buy", logoHref: "/buy", pageExtra: '<div class="rh">Your searches</div><div id="searches"></div><button type="button" class="newbtn" id="newsearch">+ New search</button>', crew, req, analytics: true });
  shell = shell.includes(MENU) ? shell.replace(MENU, MVIS + MENU) : shell.replace("</header>", MVIS + "</header>");
  // Which other products Buy may link to: the launch stage, read per request (crew always true).
  const rel = { mc: isReleased("market-check", req), tasks: isReleased("tasks", req) };
  const railFinal = '<script>window.GAS_CREW=' + (crew ? "true" : "false") + ';window.GAS_REL=' + JSON.stringify(rel) + ';</script>' + shell +
    '<div class="mvlist" id="mvlist" hidden><div class="vlist"></div><button type="button" class="mvnew" data-newsearch>+ New search</button></div>';
  const html = `<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8">${paletteHead(showPal)}<meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover">
<title>${TITLE}</title><meta name="description" content="${esc(lead)}">
<meta name="robots" content="${robots}"><link rel="canonical" href="https://goasksam.com/buy">
<meta property="og:title" content="${TITLE}"><meta property="og:description" content="${esc(lead)}"><meta property="og:url" content="https://goasksam.com/buy"><meta property="og:type" content="website"><link rel="icon" href="/favicon.ico" sizes="any"><meta name="theme-color" content="#FAF8F4">
${FONT_LINKS}<style>${PAGE_CSS}${AUTH_SIGNBAR_CSS}${SHELL_CSS}${BUY_CSS}${CARD_RULES_CSS}${RUNG_CSS}${BUY_CARD_CSS}${LANDING_CSS}${SELLS_FOR_CARD_CSS}${brandPaletteCss(crew)}${CONSENT_BANNER_CSS}</style></head><body>
${showPal ? paletteSwitcherHtml() + "\n" : ""}${AUTH_SIGNBAR_HTML}
${railFinal}
<main class="buymain">
<div class="scroll" id="scroll"><div class="col">${late ? landingHtml({ updated, band, tasks: rel.tasks }).replace('<div id="lead" class="lk">', '<div id="lead" class="lk" data-late>') : landingHtml({ updated, band, tasks: rel.tasks })}<div id="convo" aria-live="polite"></div></div></div>
<div class="composer"><div class="col">
<div class="search" role="search"><label for="q" style="position:absolute;left:-9999px">Tell Sam what to change, or ask about any car</label><input id="q" autocomplete="off" enterkeyhint="send" placeholder="Tell Sam what to change, or ask about any car."><button type="button" class="mic" id="mic" aria-label="Speak instead of typing" aria-pressed="false"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 14a3 3 0 0 0 3-3V5a3 3 0 0 0-6 0v6a3 3 0 0 0 3 3zm5-3a5 5 0 0 1-10 0H5a7 7 0 0 0 6 6.92V21h2v-3.08A7 7 0 0 0 19 11h-2z"/></svg></button><button type="button" class="go sendbtn" id="go" aria-label="Search"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9 6l6 6-6 6"/></svg></button></div>
</div></div>
</main>
${SHELL_MAIN_CLOSE}
<div id="detail" hidden></div>
${CONSENT_BANNER_HTML}
<script>${SHELL_JS}</script>
<script>window.gasIsGuestLink=window.gasIsGuestLink||function(){return false};window.GAS_AUTH_MODE="topbar";</script>
<script src="/js/auth.js" defer></script>
<script>${AUTH_SIGNBAR_MIRROR_JS}</script>
<script>${SELLS_FOR_CARD_JS}</script>
<script>${CLIENT.replace("__KEEP_ICON__", () => JSON.stringify(KEEP_ICON)).replace("/*__PRIOR__*/", () => PRIOR_JS)}</script>
<script src="/api/track?js=1" defer></script>
<script>${CONSENT_BANNER_JS}</script>${showPal ? `<script>${PALETTE_SWITCHER_JS}</script>` : ""}</body></html>`;
  // Referrer logging (search measurement). Runs on a cache MISS only (the page is edge-cached 10 min),
  // so this samples origin hits, which includes crawlers that bypass the edge; cached hits are not seen.
  // Never holds the page: queued, written in a batch after the response.
  queueView(supabaseEnv(), { path: "/buy", referer: req.headers["referer"] || req.headers["referrer"], userAgent: req.headers["user-agent"] });
  res.setHeader("Content-Type", "text/html; charset=utf-8");
  res.setHeader("X-Robots-Tag", robots);
  // Crew's full nav (and, Oct 2026, the brand palette override) is never shared or stored. The
  // public response (no crew cookie) is identical for every anonymous visitor, so it is safely
  // cacheable at the shared edge with no Vary at all - a prior `Vary: Cookie` made the cache key
  // the raw cookie string, which differs per visitor and was an effectively permanent MISS.
  // crew alone is not enough: an INVALID gas_crew cookie (expired, made up, or stale) still
  // computes crew=false and would get the PUBLIC, cacheable header - and the edge has no Vary on
  // Cookie, so that cached entry could later be served to a REAL crew request for the same bare
  // URL (the same cache-poisoning gap fixed on Market Check/business/spec/publicConfig/history
  // this quarter - closing it here too now that this page also varies its palette by crew).
  // A cold instance that rendered before the example search finished (band undefined) is cached only
  // briefly, so the landing's example band and chips are never held out of the shared cache for long.
  const hasCrewCookie = /(?:^|;\s*)gas_crew=/.test(String(req.headers.cookie || ""));
  // A request carrying the server credential may also carry the test-only stage override (lib/_launchStage.js),
  // so its page is never put in the shared cache either: the public must always get the real stage.
  // LAUNCH-STAGE SAFETY, round 2 (Oct 2026, same production incident, api/marketCheck.js has the
  // full writeup): the stale-while-revalidate=3600 tail this page's "band" branch used is the same
  // risk at a smaller scale - removed, and public caching of EITHER branch now also requires
  // fullyLaunched() (every gated product released for crew and public alike), not just "no server
  // credential", so a stage rollback can never be outlived by a cached entry here either.
  res.setHeader("Cache-Control", (crew || hasCrewCookie || hasServerCredential(req) || !fullyLaunched() || showPal) ? "private, no-store" : late || band === undefined ? "public, s-maxage=30" : "public, s-maxage=600");
  res.status(200).send(html);
}
